using Pre2Port.Native;

namespace Pre2Port.Game.Frontend;

/// <summary>
/// Port-only (FULLSCREEN=WIDESCREEN, presentation only): side margins of the press-1/2 MAIN MENU, generated by RULES from the game's own
/// 320x200 frame (MENU.SQZ). Same mechanism as <see cref="WideArt"/> (PRESENT); kept in its own file so the PRESENT rules stay untouched.
/// No image data is stored: imagen/menuextendido.png (a hand-widened menu, repainted at ~3.53x with 109/121 native columns each side and
/// ~29 extra black rows, so its centre does not coincide with the 320x200 frame) was used only as a visual reference to choose the bands and palms below.
/// Rule per band of rows: the margin pixel at distance d from the frame edge copies the frame pixel at distance s from that edge, where
/// s walks the strip [0, W) back and forth (mirror, continuous seam). Each tile of W pixels (k = d / W) moves its source row by dy(k)
/// (amplitude Step, reflected at the band edge) so ferns do not repeat identically. Then one palm per margin is re-stamped from the frame's own centre palm
/// (see <see cref="Palm"/>). Pixels are the frame's own palette indices (selection by index, never by colour), so the menu fade applies unchanged.
/// </summary>
public static class WideMenuArt
{
    /// <summary>One band of rows: [Y0, Y1), strip width W, row-shift amplitude Step (0 = none). Cut &gt; 0 (right side only): up to distance Cut (+ a per-row
    /// ragged 0..Jit) the margin keeps mirroring the frame's right strip (the trunk goes on), then from there on it continues with the frame's LEFT edge
    /// (wrap-around, same row, Left rule at distance d - cut), because the right edge is a tree trunk that ends a few pixels beyond the frame.</summary>
    readonly record struct Band(int Y0, int Y1, int W, int Step, int Cut = 0, int Jit = 0);

    // Left: gradient sky with its dither (0..97), horizon palms and hills (98..137; strip 48 = the "1-START" glyphs begin at x=51, so never wider),
    // grass and ferns (138..171), dark roots (172..199). No row shift in the horizon (it would break the sky gradient into boxes).
    static readonly Band[] Left = { new(0, 98, 8, 0), new(98, 138, 48, 0), new(138, 172, 48, 5), new(172, 200, 48, 3) };
    // Right: sky (0..47; the logo "K" and its palm leaves end before the last 8 columns), trunk top (48..63: 2 px), trunk (64..111: 7..8 px, own mirrored texture)
    // and trunk with sky gaps (112..159: 8..10 px), then the left edge wraps in (sky, hills, small palms); ferns (160..199).
    static readonly Band[] Right = { new(0, 48, 8, 0), new(48, 64, 5, 0, 2), new(64, 112, 5, 0, 7, 1), new(112, 160, 5, 0, 8, 2), new(160, 200, 48, 5) };

    // Palm stamp (frame centre palm: crown x 114..170, rows 74..118; trunk x 136..145, rows 106..123; text glyphs start at row 124).
    // Only pixels whose palette index is a leaf (crown) or a trunk index are copied, so the sky of the margin (row-only gradient) shows through.
    static readonly byte[] Leaf = { 6, 8, 9, 10, 24, 25 }, Trunk = { 2, 3, 11, 13, 22 };
    const int CrownX0 = 114, CrownX1 = 170, CrownY0 = 74, CrownY1 = 118, TrunkX0 = 136, TrunkX1 = 145, TrunkY0 = 106, TrunkLoop = 115, TrunkLoopEnd = 123, Ground = 138;
    const int PalmMargin = 70;   // a margin narrower than this (16:9, 16:10...) gets no stamp: a palm cut by the window edge would look wrong

    /// <summary>Copies the 320 frame <paramref name="src"/> centred into <paramref name="dst"/> (palette included) and fills both margins by the band rules.</summary>
    public static void Menu(Framebuffer src, Framebuffer dst)
    {
        int w = dst.Width, sw = src.Width, m = (w - sw) / 2, mr = w - m - sw;
        Array.Copy(src.Palette, dst.Palette, dst.Palette.Length);
        for (int y = 0; y < dst.Height; y++) Array.Copy(src.Pixels, y * sw, dst.Pixels, y * w + m, sw);
        Fill(src, dst, Left, m, left: true);
        Fill(src, dst, Right, mr, left: false);
        // left palm centred 41 px beyond the frame edge, crown 14 rows up; right palm mirrored, 40 px beyond, 32 rows up (taller trunk)
        if (m >= PalmMargin) Palm(src, dst, m - 182, mirror: false, dy: -14);
        if (mr >= PalmMargin) Palm(src, dst, m + 502, mirror: true, dy: -32);
    }

    /// <summary>Stamps the centre palm: destination canvas x of frame column sx is x + sx (or x - sx when mirrored), rows moved by dy.</summary>
    static void Palm(Framebuffer src, Framebuffer dst, int x, bool mirror, int dy)
    {
        int w = dst.Width, sw = src.Width;
        int Xd(int sx) => mirror ? x - sx : x + sx;
        bool Has(byte[] set, byte v) => Array.IndexOf(set, v) >= 0;
        // trunk first (the crown covers its top), rows from the trunk top down to the ground line, the 9-row loop repeating below row 123
        for (int yd = TrunkY0 + dy; yd < Ground; yd++)
        {
            int sy = TrunkY0 + (yd - TrunkY0 - dy);
            if (sy > TrunkLoopEnd) sy = TrunkLoop + (sy - TrunkLoop) % (TrunkLoopEnd - TrunkLoop + 1);
            if (yd < 0) continue;
            for (int sx = TrunkX0; sx <= TrunkX1; sx++)
            {
                byte v = src.Pixels[sy * sw + sx];
                int xd = Xd(sx);
                if (Has(Trunk, v) && xd >= 0 && xd < w) dst.Pixels[yd * w + xd] = v;
            }
        }
        for (int sy = CrownY0; sy < CrownY1; sy++)
        {
            int yd = sy + dy;
            if (yd < 0 || yd >= dst.Height) continue;
            for (int sx = CrownX0; sx <= CrownX1; sx++)
            {
                byte v = src.Pixels[sy * sw + sx];
                int xd = Xd(sx);
                if (Has(Leaf, v) && xd >= 0 && xd < w) dst.Pixels[yd * w + xd] = v;
            }
        }
    }

    static void Fill(Framebuffer src, Framebuffer dst, Band[] bands, int margin, bool left)
    {
        int w = dst.Width, sw = src.Width, m = (w - sw) / 2;
        foreach (var b in bands)
            for (int y = b.Y0; y < b.Y1 && y < dst.Height; y++)
            {
                int cut = b.Cut == 0 ? 0 : b.Cut + y * 7 % (b.Jit + 1);   // ragged end of the trunk
                for (int d = 0; d < margin; d++)
                {
                    bool wrap = cut > 0 && d >= cut;
                    var r = wrap ? Left.First(l => y >= l.Y0 && y < l.Y1) : b;
                    int dd = wrap ? d - b.Cut : d;   // the wrapped content does not shear with the ragged edge
                    int k = dd / r.W, t = dd % (2 * r.W), s = t < r.W ? t : 2 * r.W - 1 - t;
                    int dy = r.Step == 0 ? 0 : k * r.Step % (2 * r.Step + 1) - r.Step;
                    int sy = y + dy;
                    if (sy < r.Y0) sy = 2 * r.Y0 - sy; else if (sy >= r.Y1) sy = 2 * (r.Y1 - 1) - sy;   // reflect at the band edge (a clamp would smear one row)
                    sy = Math.Clamp(sy, r.Y0, r.Y1 - 1);
                    byte v = src.Pixels[sy * sw + (left || wrap ? s : sw - 1 - s)];
                    dst.Pixels[y * w + (left ? m - 1 - d : m + sw + d)] = v;
                }
            }
    }
}
